:root {
  --bg: #1b1f2a;
  --card: #252b3a;
  --accent: #4ade80;
  --accent-dark: #22c55e;
  --text: #e7ecf3;
  --muted: #9aa7bd;
  --danger: #f87171;
  --radius: 14px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  background: radial-gradient(circle at 50% 0%, #2a3142, var(--bg) 70%);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.app {
  width: 100%;
  max-width: 460px;
  background: var(--card);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.45);
}

.hud {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}

h1 {
  font-size: 1.35rem;
  margin: 0;
  letter-spacing: 0.5px;
}

.score-box {
  display: flex;
  align-items: baseline;
  gap: 8px;
  background: #1f2533;
  padding: 6px 12px;
  border-radius: 10px;
}

.label { color: var(--muted); font-size: 0.85rem; text-transform: uppercase; letter-spacing: 1px; }
.score { font-size: 1.25rem; font-weight: 700; color: var(--accent); }

.board-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 12px;
  overflow: hidden;
  background: #141925;
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
  padding: 24px;
  background: rgba(20, 25, 37, 0.92);
  text-align: center;
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay h2 {
  margin: 0 0 4px;
  color: var(--accent);
  font-size: 1.2rem;
}

.overlay p { margin: 0; color: var(--muted); line-height: 1.5; }
.overlay strong { color: var(--text); }
.hint { font-size: 0.9rem; }

kbd {
  background: #2f3748;
  border-radius: 6px;
  padding: 2px 6px;
  font-size: 0.85rem;
  color: var(--text);
}

.controls {
  display: flex;
  gap: 12px;
  margin-top: 18px;
}

button {
  flex: 1;
  font: inherit;
  font-weight: 600;
  padding: 12px 16px;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  background: var(--accent);
  color: #0b1f12;
  transition: background 0.15s ease, transform 0.05s ease;
}

button:hover { background: var(--accent-dark); }
button:focus-visible { outline: 3px solid #a7f3d0; outline-offset: 2px; }
button:active { transform: translateY(1px); }

button.secondary {
  background: #2f3748;
  color: var(--text);
}
button.secondary:hover { background: #3a4459; }

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  body { padding: 12px; }
  .app { padding: 16px; }
  h1 { font-size: 1.15rem; }
  .overlay { padding: 16px; }
  .overlay p { font-size: 0.9rem; }
}

(function () {
  "use strict";

  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");
  const scoreEl = document.getElementById("score");
  const overlay = document.getElementById("overlay");
  const overlayTitle = document.getElementById("overlay-title");
  const pauseBtn = document.getElementById("pauseBtn");
  const restartBtn = document.getElementById("restartBtn");
  const statusEl = document.getElementById("status");

  const COLS = 20;
  const ROWS = 20;
  const CELL = canvas.width / COLS;
  const TICK_MS = 130;

  const COLORS = {
    bg: "#141925",
    grid: "#1c2230",
    snake: "#4ade80",
    head: "#a7f3d0",
    food: "#f87171"
  };

  let snake, dir, nextDir, food, score, state, timer;
  // state: "paused" | "running" | "over"

  function reset() {
    snake = [{ x: 9, y: 10 }, { x: 8, y: 10 }, { x: 7, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    scoreEl.textContent = "0";
    placeFood();
    state = "paused";
    clearInterval(timer);
    timer = null;
    pauseBtn.textContent = "Start";
    pauseBtn.setAttribute("aria-pressed", "true");
    pauseBtn.classList.remove("secondary");
    showOverlay("How to Play", [
      "Use the arrow keys to steer the snake.",
      "Eat the food to grow and score points. Don't hit the walls or yourself!",
      "Press Space or click Start to begin."
    ]);
    setStatus("Game paused. Press Space or Start to play.");
    draw();
  }

  function placeFood() {
    let spot;
    do {
      spot = { x: Math.floor(Math.random() * COLS), y: Math.floor(Math.random() * ROWS) };
    } while (snake.some((s) => s.x === spot.x && s.y === spot.y));
    food = spot;
  }

  function setStatus(msg) {
    statusEl.textContent = msg;
  }

  function showOverlay(title, lines) {
    overlayTitle.textContent = title;
    while (overlay.children.length > 1) overlay.removeChild(overlay.lastChild);
    lines.forEach((line) => {
      const p = document.createElement("p");
      p.textContent = line;
      overlay.appendChild(p);
    });
    overlay.classList.remove("hidden");
  }

  function hideOverlay() {
    overlay.classList.add("hidden");
  }

  function start() {
    if (state === "over") reset();
    state = "running";
    hideOverlay();
    pauseBtn.textContent = "Pause";
    pauseBtn.setAttribute("aria-pressed", "false");
    pauseBtn.classList.add("secondary");
    setStatus("Game running. Use arrow keys to move.");
    clearInterval(timer);
    timer = setInterval(tick, TICK_MS);
  }

  function pause() {
    if (state !== "running") return;
    state = "paused";
    clearInterval(timer);
    timer = null;
    pauseBtn.textContent = "Resume";
    pauseBtn.setAttribute("aria-pressed", "true");
    pauseBtn.classList.remove("secondary");
    showOverlay("Paused", ["Press Space or click Resume to continue."]);
    setStatus("Game paused. Press Space or Resume to continue.");
  }

  function togglePause() {
    if (state === "running") pause();
    else start();
  }

  function gameOver() {
    state = "over";
    clearInterval(timer);
    timer = null;
    pauseBtn.textContent = "Play Again";
    pauseBtn.setAttribute("aria-pressed", "false");
    pauseBtn.classList.add("secondary");
    showOverlay("Game Over", [
      "Your score: " + score,
      "Press Space or click Play Again to restart."
    ]);
    setStatus("Game over. Your score is " + score + ". Press Space or Play Again to restart.");
  }

  function tick() {
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS) {
      gameOver();
      return;
    }
    if (snake.some((s) => s.x === head.x && s.y === head.y)) {
      gameOver();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = String(score);
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function draw() {
    ctx.fillStyle = COLORS.bg;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = COLORS.grid;
    ctx.lineWidth = 1;
    for (let i = 1; i < COLS; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL, 0);
      ctx.lineTo(i * CELL, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL);
      ctx.lineTo(canvas.width, i * CELL);
      ctx.stroke();
    }

    ctx.fillStyle = COLORS.food;
    ctx.fillRect(food.x * CELL + 2, food.y * CELL + 2, CELL - 4, CELL - 4);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? COLORS.head : COLORS.snake;
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function handleKey(e) {
    const key = e.key;
    if (key === " " || key === "Spacebar") {
      e.preventDefault();
      if (state === "over") { reset(); start(); }
      else togglePause();
      return;
    }

    if (state !== "running") return;

    const map = {
      ArrowUp: { x: 0, y: -1 },
      ArrowDown: { x: 0, y: 1 },
      ArrowLeft: { x: -1, y: 0 },
      ArrowRight: { x: 1, y: 0 }
    };
    const nd = map[key];
    if (!nd) return;
    e.preventDefault();
    if (nd.x === -dir.x && nd.y === -dir.y) return;
    nextDir = nd;
  }

  pauseBtn.addEventListener("click", function () {
    if (state === "over") { reset(); start(); }
    else togglePause();
  });

  restartBtn.addEventListener("click", function () {
    reset();
  });

  document.addEventListener("keydown", handleKey);

  reset();
})();
